const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const sacramento = ee.Geometry.Point([-121.4944, 38.5816]); // Approximate center of Sacramento
  const startDate = '2022-09-01';
  const endDate = '2022-09-30';
  const temperatureThresholdF = 110;
  const scale = 1000; // Resolution of ERA5-Land is ~9km, 1000m scale is appropriate

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(startDate, endDate)
    .filterBounds(sacramento);

  const initialSize = await collection.size().getInfo();
  if (initialSize === 0) {
    console.log("No ERA5-Land data found for Sacramento in September 2022.");
    console.log("C1");
    return;
  }
  console.log(`ERA5-Land images found: ${initialSize}`);

  // 3. Processing: Convert Kelvin to Fahrenheit
  // K -> C: C = K - 273.15
  // C -> F: F = (C * 9/5) + 32
  const toFahrenheit = function(image) {
    return image.select('temperature_2m')
      .subtract(273.15) // Convert Kelvin to Celsius
      .multiply(9 / 5) // Convert Celsius to Fahrenheit
      .add(32) // Add offset for Fahrenheit
      .rename('temperature_2m_F');
  };

  const fahrenheitCollection = collection.map(toFahrenheit);

  // Get the maximum temperature over the entire period
  const maxTempImage = fahrenheitCollection.max();

  // 4. Calculation: Extract the maximum temperature value for Sacramento
  let result = await maxTempImage.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: sacramento,
    scale: scale,
    maxPixels: 1e9
  }).get('temperature_2m_F').getInfo();

  // 5. Validation & Final Answer
  if (result === null || typeof result === 'undefined' || isNaN(result)) {
    console.log("Calculation failed: Max temperature result is None or invalid.");
    console.log("C3");
  } else {
    // Check pixel count (though for ERA5-Land, this is unlikely to be 0 after initial collection check)
    const pixelCount = await maxTempImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: sacramento,
      scale: scale,
      maxPixels: 1e9
    }).get('temperature_2m_F').getInfo();

    if (pixelCount === 0) {
      console.log("No valid pixels remain after processing for temperature.");
      console.log("C2");
      return;
    }

    console.log(`Max 2m air temp (F) in Sep 2022 for Sacramento: ${result.toFixed(2)}`);
    console.log(`Valid pixels: ${pixelCount}`);

    if (result > temperatureThresholdF) {
      console.log("A"); // Yes
    } else {
      console.log("B"); // No
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
